export const CMP_SCC_D:Record<string,CMPSccMonth>={"April":{"note":"<strong>FY begins.</strong> Ensure all new registrations (GST, PT, ESIC) are in order. March TDS has a special extended due date of 30th April. Composition dealers: CMP-08 for Q4 (Jan–Mar) due 18th April + GSTR-4 Annual Return due 30th June. <strong>📜 New law:</strong> the Income-tax Act, 2025 is now in force — income from 1 April falls under the new <em>Tax Year</em> (replacing Previous Year / Assessment Year), and the TDS forms are renumbered: salary certificate is now Form 130 (earlier 16), the annual tax-credit statement is Form 168 (earlier 26AS), and the no-deduction declaration is Form 121 (earlier 15G/15H). Returns filed during this year for the prior year continue on the earlier forms.","items":[{"id":"ap1","cat":"it","name":"TDS Deposit – March Deductions","due":"30 Apr","urgent":true,"freq":"Monthly (Special Date)","form":"Challan 281 via Income Tax Portal / TIN-NSDL","who":"Any proprietorship or partnership that deducted TDS from salary, rent, professional/technical fees, contractor payments, brokerage, commission or interest during March.","what":"Tax Deducted at Source from all payments made in the month of March must be deposited with the government by 30th April. Normally TDS is due by 7th of the following month, but March gets an extended deadline of 30th April to ease year-end pressures.","why":"Under Section 200 of the Income Tax Act 1961, the person responsible for deducting TDS must deposit it within the prescribed time. Late deposit attracts both interest and disallowance of the related expense.","penalty":"Interest @ 1.5% per month (or part of month) u/s 201(1A) from date of deduction to date of deposit. 30% of the payment on which TDS was not deducted is disallowed as a business expense u/s 40(a)(ia)."},{"id":"ap_comp1","cat":"comp","name":"CMP-08 – Q4 Tax Payment (Jan–Mar) | Composition Dealers","due":"18 Apr","urgent":true,"freq":"Quarterly (Q4)","form":"CMP-08 on GST Portal (gst.gov.in)","who":"All taxpayers registered under the GST Composition Scheme (manufacturers/traders up to ₹1.5 crore turnover, service providers up to ₹50 lakh).","what":"Pay quarterly composition tax for January–March period (Q4 of FY). Apply the applicable flat rate on Q4 turnover: 1% for traders (0.5% CGST + 0.5% SGST), 5% for restaurants (2.5% each), 6% for service providers (3% each). Ensure Q4 turnover is correctly captured including all retail sales.","why":"Composition dealers replace monthly GSTR-3B with quarterly CMP-08 payments. This is the last CMP-08 for the FY. After paying CMP-08, file GSTR-4 (annual return) by 30th June.","penalty":"Interest 18% p.a. on late payment + ₹50/day late fee (₹20/day if NIL return). Maximum late fee ₹10,000."},{"id":"ap2","cat":"gst","name":"GSTR-1 – March Outward Supplies (Monthly Filers)","due":"11 Apr","freq":"Monthly","form":"GSTR-1 on GST Portal (gst.gov.in)","who":"Regular GST taxpayers with annual aggregate turnover above ₹5 crore.","what":"Upload details of all outward supplies (sales) made during March. Includes B2B invoices, B2C large invoices, exports, credit/debit notes, advances received, and exempt/nil-rated supplies.","why":"GSTR-1 is the foundation of the GST ecosystem. Your buyers can avail Input Tax Credit (ITC) only on invoices that appear in GSTR-2B (auto-populated from your GSTR-1).","penalty":"Late fee: ₹50/day (₹20/day for Nil returns). Maximum late fee: ₹10,000 per return period."},{"id":"ap3","cat":"gst","name":"GSTR-3B – March Summary Return & GST Payment (Monthly Filers)","due":"20 Apr","freq":"Monthly","form":"GSTR-3B on GST Portal","who":"All regular GST-registered taxpayers with monthly return obligation.","what":"File summary return declaring: (1) Total outward taxable supplies & output GST; (2) Eligible Input Tax Credit; (3) Net tax payable; (4) Exempt, nil-rated and non-GST supplies. Pay the net GST through the Electronic Cash Ledger.","why":"GSTR-3B is the primary mechanism for GST payment. The GST liability computed here must be discharged on or before the due date.","penalty":"Interest @ 18% p.a. on outstanding GST from due date. Late fee: ₹50/day (₹20/day for Nil returns). Maximum: ₹10,000."},{"id":"ap4","cat":"comp","name":"GSTR-4 – Annual Return for Composition Dealers (FY 2023–24)","due":"30 Jun","urgent":true,"freq":"Annual","form":"GSTR-4 on GST Portal","who":"All taxpayers registered under the GST Composition Scheme for FY 2023–24.","what":"Annual consolidated statement of all outward supplies and inward supplies liable to reverse charge, and tax paid at flat composition rate during the entire FY April–March. Must reconcile with quarterly CMP-08 tax payments already made during the year.","why":"Composition dealers pay GST at a fixed percentage on turnover (1% for traders, 5% for restaurants, 6% for service providers) and make quarterly tax payments via CMP-08. GSTR-4 is the annual audit trail confirming all sales and taxes for the year.","penalty":"Late fee: ₹200/day (₹100 CGST + ₹100 SGST), maximum ₹5,000. Late filing blocks future amendments and may trigger departmental notices."},{"id":"ap5","cat":"lab","name":"EPF Contribution Deposit – March Wages","due":"15 Apr","freq":"Monthly","form":"ECR (Electronic Challan cum Return) via EPFO Unified Portal","who":"All establishments employing 20 or more persons. Once covered, obligation continues even if headcount later falls below 20.","what":"Deposit Provident Fund contributions for March: Employee share 12% of basic wages + DA. Employer share 12% (3.67% EPF + 8.33% EPS). Admin charges 0.50% + EDLI 0.50%.","why":"The Employees' Provident Funds Act 1952 mandates PF contribution to build a retirement corpus for workers. PF also provides insurance (EDLI) and pension (EPS) benefits.","penalty":"Damages for delay: 5% p.a. up to 2 months; 10% for 2–4 months; 15% for 4–6 months; 25% beyond 6 months. Interest @ 12% p.a. Criminal prosecution u/s 14 for persistent defaults."},{"id":"ap6","cat":"lab","name":"ESIC Contribution Deposit – March Wages","due":"15 Apr","freq":"Monthly","form":"ESIC Portal (esic.in) – Online Challan","who":"Establishments with 10 or more employees. Covers employees earning gross wages up to ₹21,000/month.","what":"Deposit ESI contributions for March wages: Employer contribution 3.25% + Employee contribution 0.75% of gross wages. Total 4%.","why":"The ESI Act 1948 provides insured workers and their families access to free medical care, cash compensation during sick leave, maternity benefit, disability allowance, and dependents' pension.","penalty":"Simple interest @ 12% p.a. + damages up to 25%. Criminal prosecution for persistent non-compliance."},{"id":"ap7","cat":"lab","name":"Professional Tax – March Deduction & Deposit","due":"Last day of Apr","freq":"Monthly","form":"State PT Portal / Treasury Challan (Form III-B in Maharashtra)","who":"All employers in PT-applicable states: Maharashtra, Karnataka, Gujarat, AP, Tamil Nadu, West Bengal etc.","what":"Deduct PT from March employee salaries per state slab and deposit. Maharashtra: ≤₹7,500 → NIL; ₹7,501–₹10,000 → ₹175/month; >₹10,000 → ₹200/month (₹300 in February).","why":"PT is levied by state governments under Article 276 of the Constitution. Employer's statutory duty to deduct and deposit.","penalty":"Maharashtra: Penalty up to 3× unpaid tax + interest @ 1.25% per month. Failure to register: up to ₹5,000."}]},"May":{"note":"<strong>Q4 TDS Return deadline is 31st May.</strong> File Form 24Q (salary TDS) and 26Q (other TDS) for January–March quarter. Also ESIC half-yearly return (Oct–Mar) due 11th May.","items":[{"id":"my1","cat":"it","name":"TDS Deposit – April Deductions","due":"7 May","freq":"Monthly","form":"Challan 281 – Income Tax Portal","who":"All entities that deducted TDS on April payments.","what":"Deposit TDS deducted from all payments made in April. Use separate challans for different TDS sections (Sec 192 salary, 194I rent, 194J professional fees, etc.).","why":"Section 200 requires TDS to be deposited by the 7th of the following month (except March due 30th April).","penalty":"Interest @ 1.5%/month from date of deduction to date of deposit. Expense disallowed 30% if TDS not deducted."},{"id":"my2","cat":"it","name":"TDS Return – Q4 (January–March) | Form 24Q & 26Q","due":"31 May","urgent":true,"freq":"Quarterly","form":"Form 24Q (Salary) / Form 26Q (Other Payments) – via TRACES/ITD Portal","who":"All deductors who deducted TDS during January to March quarter.","what":"File quarterly TDS return with PAN-wise details of deductees, amounts paid/credited, TDS deducted and challans. Form 24Q: TDS on salary including full salary computation for the year in Q4. Form 26Q: All other TDS payments.","why":"Q4 return enables deductees to see full year TDS credit in Form 26AS. Q4 return requires the complete annual salary statement, making it the most critical quarter.","penalty":"Late fee u/s 234E: ₹200/day from due date until filing (capped at TDS amount). u/s 271H: Additional penalty ₹10,000 to ₹1,00,000."},{"id":"my3","cat":"gst","name":"GSTR-1 – April (Monthly Filers)","due":"11 May","freq":"Monthly","form":"GSTR-1 on GST Portal","who":"Regular GST taxpayers with monthly filing obligation (turnover > ₹5 crore).","what":"Upload all April sales invoices, debit/credit notes, and advance receipts. HSN summary mandatory.","why":"Enables buyer ITC claims for April purchases. Late GSTR-1 blocks buyers' ITC for the month.","penalty":"₹50/day (₹20/day Nil returns), maximum ₹10,000."},{"id":"my4","cat":"gst","name":"GSTR-3B – April (Monthly Filers)","due":"20 May","freq":"Monthly","form":"GSTR-3B on GST Portal","who":"All regular GST taxpayers.","what":"File summary return and pay net GST liability for April. Match ITC with GSTR-2B before filing.","why":"Primary return for GST payment. Excess ITC claimed beyond GSTR-2B attracts Rule 36(4) restrictions.","penalty":"Interest 18% p.a. on outstanding liability + late fee ₹50/day."},{"id":"my5","cat":"lab","name":"EPF Contribution – April Wages","due":"15 May","freq":"Monthly","form":"ECR via EPFO Portal","who":"All EPFO-covered establishments.","what":"Deposit April wage month PF contributions: Employee 12% + Employer 12% + Admin 0.50% + EDLI 0.50%.","why":"Monthly statutory obligation. Delay affects employees' UAN passbook and pension calculations.","penalty":"Damages 5–25% of dues + interest 12% p.a."},{"id":"my6","cat":"lab","name":"ESIC Contribution – April Wages","due":"15 May","freq":"Monthly","form":"ESIC Portal (esic.in)","who":"Establishments with 10+ employees (eligible employees earning ≤₹21,000/month).","what":"Deposit ESIC contributions for April: Employer 3.25% + Employee 0.75% of gross wages.","why":"Monthly statutory obligation. Delays disqualify employees from ESIC medical and cash benefits.","penalty":"Interest 12% p.a. + damages up to 25%."},{"id":"my7","cat":"lab","name":"ESIC Half-Yearly Return – October to March","due":"11 May","urgent":true,"freq":"Half-Yearly","form":"Form 7-A / Return via ESIC Online Portal","who":"All ESIC registered employers.","what":"File the ESIC contribution return for the second half of FY (October–March) declaring wages paid per employee, contribution amounts, and contribution periods.","why":"Mandatory reconciliation return under ESI Act. This data determines workers' benefit eligibility. Delays can affect employees' ESIC cards and medical access.","penalty":"Fine up to ₹5,000 under Section 85 of the ESI Act."},{"id":"my8","cat":"lab","name":"Professional Tax – April Deduction & Deposit","due":"Last day of May","freq":"Monthly","form":"State PT Portal / Treasury","who":"PT-applicable employers.","what":"Deduct PT from April salaries and deposit with state government.","why":"Monthly PT deduction and deposit obligation.","penalty":"State-specific penalties; interest ~1.25%/month in Maharashtra."}]},"June":{"note":"<strong>Three critical deadlines:</strong> Advance Tax 1st installment (15th), Form 16 for salary TDS (15th), and Form 16A for Q4 non-salary TDS (15th). Don't club them — each requires separate action.","items":[{"id":"jn1","cat":"it","name":"TDS Deposit – May Deductions","due":"7 Jun","freq":"Monthly","form":"Challan 281","who":"All TDS deductors.","what":"Deposit TDS deducted from May payments with the IT department.","why":"Monthly statutory obligation u/s 200.","penalty":"Interest 1.5%/month on late deposit."},{"id":"jn2","cat":"it","name":"Advance Tax – 1st Installment (≥15% of Annual Tax)","due":"15 Jun","urgent":true,"freq":"Quarterly","form":"Challan 280 – Income Tax Portal","who":"All proprietors and partnership firms where estimated annual Income Tax liability exceeds ₹10,000.","what":"Pay at least 15% of the estimated total tax liability for FY 2024–25. Steps: (1) Estimate annual business income, (2) Deduct 80-series deductions, (3) Compute tax, (4) Pay 15% now. Schedule: 15% by 15 Jun · 45% by 15 Sep · 75% by 15 Dec · 100% by 15 Mar.","why":"Advance tax ensures income earners pay tax proportionally as they earn. Accurate estimation avoids penal interest.","penalty":"Interest u/s 234C: 1%/month for 3 months on shortfall in 1st installment. u/s 234B: 1%/month if total advance tax < 90% of assessed tax by 31st March."},{"id":"jn3","cat":"it","name":"Form 16 – Salary TDS Certificate (FY 2023–24)","due":"15 Jun","urgent":true,"freq":"Annual","form":"Form 16 (Part A from TRACES + Part B prepared by employer)","who":"All employers who deducted TDS u/s 192 on any employee's salary during FY 2023–24.","what":"Issue Form 16 to each employee: Part A (from TRACES) with quarter-wise TDS and challan details; Part B with detailed salary breakup, all allowances, deductions u/s 80C/80D, and final tax computation.","why":"Form 16 is the salary TDS certificate employees use to file their ITR, claim refunds, and as income proof for loans and visas.","penalty":"Penalty u/s 272A: ₹100 per day for each certificate delayed, for each employee affected."},{"id":"jn4","cat":"it","name":"Form 16A – Non-Salary TDS Certificate (Q4: Jan–Mar)","due":"15 Jun","freq":"Quarterly","form":"Form 16A generated from TRACES Portal","who":"All entities that deducted TDS from non-salary payments during January–March.","what":"Issue TDS certificates to each deductee (vendor, landlord, consultant) for TDS deducted during Q4. Download from TRACES after Q4 TDS return has been processed.","why":"Deductees use Form 16A to reconcile TDS in Form 26AS and claim TDS credit in their ITR.","penalty":"₹100/day u/s 272A for delay in issuance to each deductee."},{"id":"jn5","cat":"gst","name":"GSTR-1 – May (Monthly Filers)","due":"11 Jun","freq":"Monthly","form":"GSTR-1 on GST Portal","who":"Regular taxpayers (monthly filers).","what":"Report all May sales invoices and outward supply details.","why":"Enables buyer ITC claims for May purchases.","penalty":"₹50/day max ₹10,000."},{"id":"jn6","cat":"gst","name":"GSTR-3B – May (Monthly Filers)","due":"20 Jun","freq":"Monthly","form":"GSTR-3B on GST Portal","who":"All regular GST taxpayers.","what":"File summary return and pay net GST for May.","why":"Primary GST payment return for May.","penalty":"Interest 18% p.a. + ₹50/day late fee."},{"id":"jn8","cat":"lab","name":"EPF Contribution – May Wages","due":"15 Jun","freq":"Monthly","form":"ECR via EPFO Portal","who":"EPFO-covered establishments.","what":"Deposit May PF contributions (Employee 12% + Employer 12% + charges).","why":"Monthly statutory obligation under EPF Act.","penalty":"Damages 5–25% + interest 12% p.a."},{"id":"jn9","cat":"lab","name":"ESIC Contribution – May Wages","due":"15 Jun","freq":"Monthly","form":"ESIC Portal","who":"ESIC-covered establishments.","what":"Deposit ESIC contributions for May (Employer 3.25% + Employee 0.75%).","why":"Monthly statutory obligation under ESI Act.","penalty":"Interest 12% p.a. + damages up to 25%."},{"id":"jn10","cat":"lab","name":"Professional Tax – May Deduction & Deposit","due":"Last day of Jun","freq":"Monthly","form":"State PT Portal","who":"PT-applicable employers.","what":"Deduct PT from May salaries and deposit with state government.","why":"Monthly PT obligation under state law.","penalty":"State-specific interest and penalty."}]},"July":{"note":"<strong>Major month:</strong> Q1 TDS Return (31 Jul), ITR for non-audit cases (31 Jul), GSTR-1/3B for QRMP quarterly filers (Q1), and <strong>CMP-08 Q1 for composition dealers (18 Jul)</strong>. Start gathering ITR documents.","items":[{"id":"jl1","cat":"it","name":"TDS Deposit – June Deductions","due":"7 Jul","freq":"Monthly","form":"Challan 281","who":"All TDS deductors.","what":"Deposit TDS deducted from June payments.","why":"Monthly statutory obligation.","penalty":"Interest 1.5%/month on late deposit."},{"id":"jl2","cat":"it","name":"TDS Return – Q1 (April–June) | Form 24Q & 26Q","due":"31 Jul","urgent":true,"freq":"Quarterly","form":"Form 24Q / Form 26Q via ITD Portal or TIN-FC","who":"All deductors who deducted TDS during April–June.","what":"File Q1 quarterly TDS return with PAN-wise details of deductees, amounts paid, TDS deducted and deposited. Form 24Q for salary TDS. Form 26Q for all other TDS.","why":"Enables deductees to see TDS credit in Form 26AS for the quarter. Required before Form 16A for Q1 can be issued.","penalty":"₹200/day u/s 234E (max = TDS amount) + penalty u/s 271H."},{"id":"jl3","cat":"it","name":"Income Tax Return – Proprietorship / Firms (Non-Audit Cases)","due":"31 Jul","urgent":true,"freq":"Annual","form":"ITR-3 (Proprietor) / ITR-5 (Partnership Firm)","who":"Proprietorships and partnership firms not required to get accounts audited u/s 44AB.","what":"File annual ITR reporting total business/professional income, partner's remuneration and interest, deductions u/s 80C/80D etc., brought forward losses, self-assessment tax payments.","why":"Filing ITR is mandatory for all business entities with income above basic exemption. ITR is the basis for tax refunds, carrying forward losses, loan applications, and visa processing.","penalty":"Late fee u/s 234F: ₹5,000 if filed after 31 Jul (₹1,000 if income ≤₹5 lakh). Loss carry-forward denied. Interest u/s 234A on outstanding tax."},{"id":"jl4","cat":"gst","name":"GSTR-1 – June (Monthly Filers)","due":"11 Jul","freq":"Monthly","form":"GSTR-1 on GST Portal","who":"Monthly filers (turnover > ₹5 crore).","what":"Report all June sales invoices and outward supply details.","why":"Enables buyer ITC for June purchases.","penalty":"₹50/day max ₹10,000."},{"id":"jl5","cat":"gst","name":"GSTR-1 – Q1 (Apr–Jun) | QRMP Quarterly Filers","due":"13 Jul","freq":"Quarterly (Q1)","form":"GSTR-1 on GST Portal","who":"Taxpayers under QRMP scheme (turnover ≤ ₹5 crore).","what":"Upload Q1 invoices (April–June) in GSTR-1. Monthly IFF uploads during the quarter are optional but help buyers get timely ITC.","why":"QRMP scheme allows smaller taxpayers to file GSTR-1 quarterly. Monthly GST payments are made via PMT-06.","penalty":"₹50/day (₹20 Nil), max ₹10,000."},{"id":"jl6","cat":"gst","name":"GSTR-3B – June (Monthly Filers)","due":"20 Jul","freq":"Monthly","form":"GSTR-3B on GST Portal","who":"All regular GST taxpayers.","what":"File summary return and pay net GST for June.","why":"Primary GST payment return for June.","penalty":"Interest 18% p.a. + ₹50/day."},{"id":"jl7","cat":"gst","name":"GSTR-3B – Q1 (Apr–Jun) | QRMP Quarterly Filers","due":"22 Jul","freq":"Quarterly (Q1)","form":"GSTR-3B on GST Portal","who":"QRMP scheme taxpayers.","what":"File Q1 GSTR-3B declaring consolidated ITC and GST liability for April–June. Adjust for monthly PMT-06 payments already made.","why":"Quarterly settlement of GST for QRMP filers.","penalty":"Interest 18% p.a. on shortfall + late fee ₹50/day."},{"id":"jl8","cat":"comp","name":"CMP-08 – Q1 Tax Payment (Apr–Jun) | Composition Dealers","due":"18 Jul","urgent":true,"freq":"Quarterly (Q1)","form":"CMP-08 on GST Portal","who":"GST Composition scheme taxpayers.","what":"Pay quarterly composition tax for April–June period on the quarter's turnover at the applicable flat rate (1% traders, 5% restaurants, 6% service providers). CMP-08 is a statement-cum-challan — it is both the payment and the return.","why":"Composition dealers pay tax quarterly rather than monthly. This replaces GSTR-3B for composition taxpayers. Ensure accurate Q1 turnover is computed before filing.","penalty":"Interest 18% p.a. + ₹50/day late fee. Maximum late fee ₹10,000."},{"id":"jl9","cat":"lab","name":"EPF Contribution – June Wages","due":"15 Jul","freq":"Monthly","form":"ECR via EPFO Portal","who":"EPFO-covered establishments.","what":"Deposit June PF contributions.","why":"Monthly statutory obligation.","penalty":"Damages 5–25% + interest 12% p.a."},{"id":"jl10","cat":"lab","name":"ESIC Contribution – June Wages","due":"15 Jul","freq":"Monthly","form":"ESIC Portal","who":"ESIC-covered establishments.","what":"Deposit ESIC contributions for June.","why":"Monthly statutory obligation.","penalty":"Interest 12% p.a. + damages up to 25%."},{"id":"jl11","cat":"lab","name":"Labour Welfare Fund (LWF) – Jan–Jun Contribution","due":"15 Jul","freq":"Half-Yearly","form":"State LWF Authority (Online/Treasury)","who":"All establishments in states where LWF is applicable: Maharashtra, Karnataka, AP, MP, Gujarat, Kerala etc.","what":"Deposit LWF contributions for January–June period. Maharashtra rates: Employee ₹6/month + Employer ₹12/month. Other states have different rates.","why":"LWF provides welfare services to industrial workers including housing, education, and medical aid. Administered by the State Labour Welfare Board.","penalty":"Interest and penalty under respective State LWF Act. Maharashtra: interest 1%/month + fine up to ₹500."},{"id":"jl12","cat":"lab","name":"Professional Tax – June Deduction & Deposit","due":"Last day of Jul","freq":"Monthly","form":"State PT Portal","who":"PT-applicable employers.","what":"Deduct PT from June salaries and deposit with state government.","why":"Monthly PT obligation.","penalty":"State-specific penalties."}]},"August":{"note":"<strong>Form 16A for Q1 due on 15th August.</strong> This is 15 days after the Q1 TDS return due date (31 Jul). Ensure Q1 TDS return was filed first and TRACES has processed it.","items":[{"id":"ag1","cat":"it","name":"TDS Deposit – July Deductions","due":"7 Aug","freq":"Monthly","form":"Challan 281","who":"All TDS deductors.","what":"Deposit TDS deducted from July payments.","why":"Monthly statutory obligation.","penalty":"Interest 1.5%/month on late deposit."},{"id":"ag2","cat":"it","name":"Form 16A – Non-Salary TDS Certificate (Q1: Apr–Jun)","due":"15 Aug","urgent":true,"freq":"Quarterly","form":"Form 16A from TRACES Portal","who":"All entities that deducted TDS on non-salary payments during April–June.","what":"Issue Form 16A TDS certificates to deductees (vendors, landlords, consultants) for Q1. Download from TRACES after Q1 return (filed 31 Jul) has been processed.","why":"Deductees need Form 16A to reconcile TDS in their accounts and claim credit in their ITR.","penalty":"₹100/day u/s 272A for each delayed certificate."},{"id":"ag3","cat":"gst","name":"GSTR-1 – July (Monthly Filers)","due":"11 Aug","freq":"Monthly","form":"GSTR-1 on GST Portal","who":"Monthly filers.","what":"Report all July sales invoices and outward supply details.","why":"Buyer ITC depends on timely GSTR-1.","penalty":"₹50/day max ₹10,000."},{"id":"ag4","cat":"gst","name":"GSTR-3B – July (Monthly Filers)","due":"20 Aug","freq":"Monthly","form":"GSTR-3B on GST Portal","who":"All regular GST taxpayers.","what":"File summary return and pay net GST for July.","why":"Primary GST payment return.","penalty":"Interest 18% p.a. + ₹50/day."},{"id":"ag5","cat":"lab","name":"EPF Contribution – July Wages","due":"15 Aug","freq":"Monthly","form":"ECR via EPFO Portal","who":"EPFO-covered establishments.","what":"Deposit July PF contributions.","why":"Monthly statutory obligation.","penalty":"Damages 5–25% + interest 12% p.a."},{"id":"ag6","cat":"lab","name":"ESIC Contribution – July Wages","due":"15 Aug","freq":"Monthly","form":"ESIC Portal","who":"ESIC-covered establishments.","what":"Deposit ESIC contributions for July.","why":"Monthly statutory obligation.","penalty":"Interest 12% p.a. + damages up to 25%."},{"id":"ag7","cat":"lab","name":"Professional Tax – July Deduction & Deposit","due":"Last day of Aug","freq":"Monthly","form":"State PT Portal","who":"PT-applicable employers.","what":"Deduct PT from July salaries and deposit.","why":"Monthly PT obligation.","penalty":"State-specific penalties."}]},"September":{"note":"<strong>Critical month:</strong> Tax Audit Report (30 Sep) and Advance Tax 2nd installment (15 Sep). If accounts need audit, the Tax Audit Report must be filed before the ITR due date (31 Oct).","items":[{"id":"sp1","cat":"it","name":"TDS Deposit – August Deductions","due":"7 Sep","freq":"Monthly","form":"Challan 281","who":"All TDS deductors.","what":"Deposit TDS deducted from August payments.","why":"Monthly statutory obligation.","penalty":"Interest 1.5%/month on late deposit."},{"id":"sp2","cat":"it","name":"Advance Tax – 2nd Installment (Cumulative ≥45%)","due":"15 Sep","urgent":true,"freq":"Quarterly","form":"Challan 280 – Income Tax Portal","who":"All advance tax payers (proprietors and firms with tax liability > ₹10,000).","what":"Pay enough advance tax to bring total paid to at least 45% of estimated annual tax liability. Reassess income and profit for the year (April–September actuals + October–March estimate).","why":"The September installment is the midyear check-in. Revise estimates if business performance has changed significantly.","penalty":"Interest u/s 234C: 1% per month for 3 months on shortfall below 45%. Also u/s 234B if overall advance tax < 90%."},{"id":"sp3","cat":"it","name":"Tax Audit Report – Form 3CA / 3CB / 3CD","due":"30 Sep","urgent":true,"freq":"Annual","form":"Form 3CA or 3CB + Form 3CD via IT Portal","who":"Proprietorships/firms with: Business turnover > ₹1 crore (₹10 crore if cash receipts & payments ≤5%), Professional receipts > ₹50 lakh.","what":"Get accounts audited by a CA who submits the audit report online. Form 3CA (if books already audited under other law) or Form 3CB (other cases) + Form 3CD with 44 clauses covering all aspects of the business.","why":"Tax audit verifies that accounts are maintained properly, income is computed correctly, and all required disclosures are made.","penalty":"Penalty u/s 271B: ½% of turnover/gross receipts or ₹1.5 lakh, whichever is lower."},{"id":"sp4","cat":"gst","name":"GSTR-1 – August (Monthly Filers)","due":"11 Sep","freq":"Monthly","form":"GSTR-1 on GST Portal","who":"Monthly filers.","what":"Report all August sales invoices.","why":"Buyer ITC depends on timely filing.","penalty":"₹50/day max ₹10,000."},{"id":"sp5","cat":"gst","name":"GSTR-3B – August (Monthly Filers)","due":"20 Sep","freq":"Monthly","form":"GSTR-3B on GST Portal","who":"All regular GST taxpayers.","what":"File summary return and pay net GST for August.","why":"Primary GST payment return.","penalty":"Interest 18% p.a. + ₹50/day."},{"id":"sp6","cat":"lab","name":"EPF Contribution – August Wages","due":"15 Sep","freq":"Monthly","form":"ECR via EPFO Portal","who":"EPFO-covered establishments.","what":"Deposit August PF contributions.","why":"Monthly statutory obligation.","penalty":"Damages 5–25% + interest 12% p.a."},{"id":"sp7","cat":"lab","name":"ESIC Contribution – August Wages","due":"15 Sep","freq":"Monthly","form":"ESIC Portal","who":"ESIC-covered establishments.","what":"Deposit ESIC contributions for August.","why":"Monthly statutory obligation.","penalty":"Interest 12% p.a. + damages up to 25%."},{"id":"sp8","cat":"lab","name":"Professional Tax – August Deduction & Deposit","due":"Last day of Sep","freq":"Monthly","form":"State PT Portal","who":"PT-applicable employers.","what":"Deduct PT from August salaries and deposit with state government.","why":"Monthly PT obligation.","penalty":"State-specific penalties."}]},"October":{"note":"<strong>Final ITR deadline for audit cases (31 Oct)</strong> and Q2 TDS Return (31 Oct). <strong>CMP-08 Q2 for composition dealers (18 Oct).</strong> Ensure Tax Audit Report was filed in September before submitting the ITR.","items":[{"id":"oc1","cat":"it","name":"TDS Deposit – September Deductions","due":"7 Oct","freq":"Monthly","form":"Challan 281","who":"All TDS deductors.","what":"Deposit TDS deducted from September payments.","why":"Monthly statutory obligation.","penalty":"Interest 1.5%/month on late deposit."},{"id":"oc2","cat":"it","name":"TDS Return – Q2 (July–September) | Form 24Q & 26Q","due":"31 Oct","urgent":true,"freq":"Quarterly","form":"Form 24Q / Form 26Q – via ITD Portal","who":"All deductors who deducted TDS during July–September.","what":"File Q2 quarterly TDS return with PAN-wise details of deductees, payments made, TDS deducted and deposited during July–September.","why":"Enables deductees to see Q2 TDS credit in Form 26AS. Required before Form 16A for Q2 can be issued.","penalty":"₹200/day u/s 234E + penalty u/s 271H."},{"id":"oc3","cat":"it","name":"ITR Filing – Audit Cases (Firms & Proprietorships)","due":"31 Oct","urgent":true,"freq":"Annual","form":"ITR-3 (Proprietor) / ITR-5 (Firm) – via IT Portal","who":"All proprietorships and partnership firms whose accounts are required to be audited u/s 44AB.","what":"File Income Tax Return after the Tax Audit Report (Form 3CA/3CB/3CD) has been submitted by the CA. ITR-5 for firms must include partners' details, firm's income computation, disallowances, brought forward losses.","why":"Extended deadline for audit cases. Missing this deadline results in late fees, denial of loss carry-forwards, and can trigger scrutiny.","penalty":"Late fee u/s 234F: ₹5,000 (₹1,000 if income ≤₹5 lakh). Loss carry-forward disallowed for returns filed after due date."},{"id":"oc4","cat":"gst","name":"GSTR-1 – September (Monthly Filers)","due":"11 Oct","freq":"Monthly","form":"GSTR-1 on GST Portal","who":"Monthly filers.","what":"Report all September sales invoices. September is also the last chance to amend invoices/claim ITC for FY 2023–24.","why":"September GSTR-3B is the last return in which ITC for the previous FY (2023–24) can be availed.","penalty":"₹50/day max ₹10,000."},{"id":"oc5","cat":"gst","name":"GSTR-3B – September (Monthly Filers)","due":"20 Oct","freq":"Monthly","form":"GSTR-3B on GST Portal","who":"All regular GST taxpayers.","what":"File summary return and pay net GST for September. Last return in which prior FY ITC (2023–24) can be availed.","why":"Critical deadline for ITC reconciliation of previous financial year. Unclaimed ITC of FY 2023–24 lapses after this return.","penalty":"Interest 18% p.a. + ₹50/day."},{"id":"oc6","cat":"gst","name":"GSTR-1 – Q2 (Jul–Sep) | QRMP Quarterly Filers","due":"13 Oct","freq":"Quarterly (Q2)","form":"GSTR-1 on GST Portal","who":"QRMP scheme taxpayers.","what":"Upload Q2 (July–September) invoices in GSTR-1.","why":"Required for buyers' ITC claims for the quarter.","penalty":"₹50/day max ₹10,000."},{"id":"oc7","cat":"gst","name":"GSTR-3B – Q2 (Jul–Sep) | QRMP Quarterly Filers","due":"22 Oct","freq":"Quarterly (Q2)","form":"GSTR-3B on GST Portal","who":"QRMP scheme taxpayers.","what":"File Q2 GSTR-3B and settle net GST liability after adjusting PMT-06 monthly payments.","why":"Quarterly GST settlement for QRMP filers.","penalty":"Interest 18% p.a. + ₹50/day."},{"id":"oc8","cat":"comp","name":"CMP-08 – Q2 Tax Payment (Jul–Sep) | Composition Dealers","due":"18 Oct","urgent":true,"freq":"Quarterly (Q2)","form":"CMP-08 on GST Portal","who":"GST Composition scheme taxpayers.","what":"Pay quarterly composition tax for July–September on the quarter's turnover at applicable flat rate. CMP-08 is a statement-cum-challan covering both payment and declaration of turnover.","why":"Quarterly payment obligation for composition dealers — replaces GSTR-3B. Ensure Q2 turnover computation is accurate before filing.","penalty":"Interest 18% p.a. + ₹50/day late fee. Maximum late fee ₹10,000."},{"id":"oc9","cat":"lab","name":"EPF Contribution – September Wages","due":"15 Oct","freq":"Monthly","form":"ECR via EPFO Portal","who":"EPFO-covered establishments.","what":"Deposit September PF contributions.","why":"Monthly statutory obligation.","penalty":"Damages 5–25% + interest 12% p.a."},{"id":"oc10","cat":"lab","name":"ESIC Contribution – September Wages","due":"15 Oct","freq":"Monthly","form":"ESIC Portal","who":"ESIC-covered establishments.","what":"Deposit ESIC contributions for September.","why":"Monthly statutory obligation.","penalty":"Interest 12% p.a. + damages up to 25%."},{"id":"oc11","cat":"lab","name":"Professional Tax – September Deduction & Deposit","due":"Last day of Oct","freq":"Monthly","form":"State PT Portal","who":"PT-applicable employers.","what":"Deduct PT from September salaries and deposit.","why":"Monthly PT obligation.","penalty":"State-specific penalties."}]},"November":{"note":"<strong>Form 16A for Q2 (Jul–Sep) due 15th November</strong> — 15 days after Q2 TDS return. ESIC half-yearly return for April–September is also due 11th November.","items":[{"id":"nv1","cat":"it","name":"TDS Deposit – October Deductions","due":"7 Nov","freq":"Monthly","form":"Challan 281","who":"All TDS deductors.","what":"Deposit TDS deducted from October payments.","why":"Monthly statutory obligation.","penalty":"Interest 1.5%/month on late deposit."},{"id":"nv2","cat":"it","name":"Form 16A – Non-Salary TDS Certificate (Q2: Jul–Sep)","due":"15 Nov","urgent":true,"freq":"Quarterly","form":"Form 16A from TRACES Portal","who":"All entities that deducted TDS on non-salary payments during July–September.","what":"Issue Form 16A certificates to deductees for Q2 TDS. Download from TRACES after Q2 return (filed 31 Oct) is processed. Distribute to each vendor, landlord, and consultant.","why":"Deductees need Q2 Form 16A to reconcile TDS in their books and claim credit in advance tax calculations.","penalty":"₹100/day u/s 272A for each delayed certificate."},{"id":"nv3","cat":"gst","name":"GSTR-1 – October (Monthly Filers)","due":"11 Nov","freq":"Monthly","form":"GSTR-1 on GST Portal","who":"Monthly filers.","what":"Report all October sales invoices and outward supply details.","why":"Buyer ITC depends on timely GSTR-1.","penalty":"₹50/day max ₹10,000."},{"id":"nv4","cat":"gst","name":"GSTR-3B – October (Monthly Filers)","due":"20 Nov","freq":"Monthly","form":"GSTR-3B on GST Portal","who":"All regular GST taxpayers.","what":"File summary return and pay net GST for October.","why":"Primary GST payment return.","penalty":"Interest 18% p.a. + ₹50/day."},{"id":"nv5","cat":"lab","name":"EPF Contribution – October Wages","due":"15 Nov","freq":"Monthly","form":"ECR via EPFO Portal","who":"EPFO-covered establishments.","what":"Deposit October PF contributions.","why":"Monthly statutory obligation.","penalty":"Damages 5–25% + interest 12% p.a."},{"id":"nv6","cat":"lab","name":"ESIC Contribution – October Wages","due":"15 Nov","freq":"Monthly","form":"ESIC Portal","who":"ESIC-covered establishments.","what":"Deposit ESIC contributions for October.","why":"Monthly statutory obligation.","penalty":"Interest 12% p.a. + damages up to 25%."},{"id":"nv7","cat":"lab","name":"ESIC Half-Yearly Return – April to September","due":"11 Nov","urgent":true,"freq":"Half-Yearly","form":"Form 7-A / Return via ESIC Online Portal","who":"All ESIC registered employers.","what":"File the ESIC contribution return for the first half of FY (April–September) declaring wages paid per employee, contribution amounts, and contribution periods.","why":"Mandatory reconciliation return under ESI Act. Determines employees' benefit eligibility for the next benefit period.","penalty":"Fine up to ₹5,000 under Section 85 of the ESI Act."},{"id":"nv8","cat":"lab","name":"Professional Tax – October Deduction & Deposit","due":"Last day of Nov","freq":"Monthly","form":"State PT Portal","who":"PT-applicable employers.","what":"Deduct PT from October salaries and deposit.","why":"Monthly PT obligation.","penalty":"State-specific penalties."}]},"December":{"note":"<strong>GSTR-9 Annual Return & Advance Tax 3rd installment</strong> are both due this month. December is a good time to review books, pending TDS, and advance tax adequacy.","items":[{"id":"dc1","cat":"it","name":"TDS Deposit – November Deductions","due":"7 Dec","freq":"Monthly","form":"Challan 281","who":"All TDS deductors.","what":"Deposit TDS deducted from November payments.","why":"Monthly statutory obligation.","penalty":"Interest 1.5%/month on late deposit."},{"id":"dc2","cat":"it","name":"Advance Tax – 3rd Installment (Cumulative ≥75%)","due":"15 Dec","urgent":true,"freq":"Quarterly","form":"Challan 280 – Income Tax Portal","who":"All advance tax payers.","what":"Pay enough to bring total cumulative advance tax paid to at least 75% of estimated annual tax. Review 9 months of actual P&L and revise annual estimate.","why":"By December, 9 months of actual data is available for reliable estimation. Accurate payment now reduces the March 15th pressure.","penalty":"Interest u/s 234C: 1% per month for 3 months on shortfall below 75%."},{"id":"dc3","cat":"gst","name":"GSTR-1 – November (Monthly Filers)","due":"11 Dec","freq":"Monthly","form":"GSTR-1 on GST Portal","who":"Monthly filers.","what":"Report all November sales invoices.","why":"Buyer ITC for November purchases.","penalty":"₹50/day max ₹10,000."},{"id":"dc4","cat":"gst","name":"GSTR-3B – November (Monthly Filers)","due":"20 Dec","freq":"Monthly","form":"GSTR-3B on GST Portal","who":"All regular GST taxpayers.","what":"File summary return and pay net GST for November.","why":"Primary GST payment return.","penalty":"Interest 18% p.a. + ₹50/day."},{"id":"dc5","cat":"gst","name":"GSTR-9 – Annual GST Return (FY 2023–24)","due":"31 Dec","urgent":true,"freq":"Annual","form":"GSTR-9 on GST Portal","who":"All regular GST taxpayers with aggregate annual turnover above ₹2 crore. (Turnover ≤₹2 crore: optional but advisable.)","what":"File annual GST return consolidating all monthly/quarterly GSTR-1 and GSTR-3B data for FY 2023–24 (April 2023 to March 2024). Includes total outward/inward supplies, ITC availed vs reversed, HSN-wise summary, and reconciliation of tax paid vs payable.","why":"GSTR-9 is the annual audit of all GST transactions. Differences (excess ITC, under-reported turnover) can be rectified here by paying additional tax and interest.","penalty":"Late fee: ₹200/day (₹100 CGST + ₹100 SGST), maximum ₹0.25% of state turnover."},{"id":"dc6","cat":"gst","name":"GSTR-9C – Reconciliation Statement (FY 2023–24)","due":"31 Dec","freq":"Annual","form":"GSTR-9C on GST Portal (self-certification)","who":"All taxpayers with aggregate annual turnover exceeding ₹5 crore during FY 2023–24.","what":"File a reconciliation statement between audited financial statements and annual GST return (GSTR-9). Reconcile turnover, taxes paid, ITC, and certify reasons for differences.","why":"GSTR-9C ensures GST returns match audited accounts. Unexplained differences trigger departmental scrutiny.","penalty":"Same as GSTR-9: ₹200/day, max 0.25% of turnover."},{"id":"dc7","cat":"lab","name":"EPF Contribution – November Wages","due":"15 Dec","freq":"Monthly","form":"ECR via EPFO Portal","who":"EPFO-covered establishments.","what":"Deposit November PF contributions.","why":"Monthly statutory obligation.","penalty":"Damages 5–25% + interest 12% p.a."},{"id":"dc8","cat":"lab","name":"ESIC Contribution – November Wages","due":"15 Dec","freq":"Monthly","form":"ESIC Portal","who":"ESIC-covered establishments.","what":"Deposit ESIC contributions for November.","why":"Monthly statutory obligation.","penalty":"Interest 12% p.a. + damages up to 25%."},{"id":"dc9","cat":"lab","name":"Professional Tax – November Deduction & Deposit","due":"Last day of Dec","freq":"Monthly","form":"State PT Portal","who":"PT-applicable employers.","what":"Deduct PT from November salaries and deposit.","why":"Monthly PT obligation.","penalty":"State-specific penalties."},{"id":"dc_shops","cat":"lab","name":"Shops & Establishment Registration – Renewal","due":"31 Dec","freq":"Annual","form":"Maharashtra Shops & Establishment registration (Aaple Sarkar / mahaonline portal)","who":"Every shop or commercial establishment registered under the Maharashtra Shops and Establishments (Regulation of Employment and Conditions of Service) Act, 2017. Establishments with up to 9 workers file a one-time intimation only; those with 10 or more workers require registration and periodic renewal.","what":"Renew the Shops & Establishment registration certificate before it lapses. The date is firm-specific, not a fixed statewide date — align it with when your registration certificate expires. Use the ⚙ Manage Compliance tool to move the month or day if your certificate renews at a different time.","why":"A valid Shops & Establishment registration is the basic licence to run the store and employ staff. It is verified during labour inspections and is a prerequisite for several other registrations and renewals.","penalty":"Operating with a lapsed or unregistered establishment attracts a fine under the Act (commonly up to ₹1,00,000, with a further daily fine for continuing default) and risk of sealing or closure."}]},"January":{"note":"<strong>Q3 TDS Return due 31st January.</strong> <strong>CMP-08 Q3 for composition dealers (18 Jan).</strong> Also check annual returns under various Labour Laws. Labour Welfare Fund contribution for Jul–Dec period may be due.","items":[{"id":"jn_1","cat":"it","name":"TDS Deposit – December Deductions","due":"7 Jan","freq":"Monthly","form":"Challan 281","who":"All TDS deductors.","what":"Deposit TDS deducted from December payments.","why":"Monthly statutory obligation.","penalty":"Interest 1.5%/month on late deposit."},{"id":"jn_2","cat":"it","name":"TDS Return – Q3 (October–December) | Form 24Q & 26Q","due":"31 Jan","urgent":true,"freq":"Quarterly","form":"Form 24Q / Form 26Q – via ITD Portal","who":"All deductors who deducted TDS during October–December.","what":"File Q3 quarterly TDS return with PAN-wise details of deductees, payments, TDS deducted and deposited during October–December.","why":"Enables deductees to see Q3 TDS credit in Form 26AS. Form 16A for Q3 (due 15 Feb) cannot be issued before this return.","penalty":"₹200/day u/s 234E + penalty u/s 271H."},{"id":"jn_3","cat":"gst","name":"GSTR-1 – December (Monthly Filers)","due":"11 Jan","freq":"Monthly","form":"GSTR-1 on GST Portal","who":"Monthly filers.","what":"Report all December sales invoices.","why":"Buyer ITC for December purchases.","penalty":"₹50/day max ₹10,000."},{"id":"jn_4","cat":"gst","name":"GSTR-3B – December (Monthly Filers)","due":"20 Jan","freq":"Monthly","form":"GSTR-3B on GST Portal","who":"All regular GST taxpayers.","what":"File summary return and pay net GST for December.","why":"Primary GST payment return.","penalty":"Interest 18% p.a. + ₹50/day."},{"id":"jn_5","cat":"gst","name":"GSTR-1 – Q3 (Oct–Dec) | QRMP Quarterly Filers","due":"13 Jan","freq":"Quarterly (Q3)","form":"GSTR-1 on GST Portal","who":"QRMP scheme taxpayers.","what":"Upload Q3 (October–December) invoices in GSTR-1.","why":"Required for buyers' ITC claims for the quarter.","penalty":"₹50/day max ₹10,000."},{"id":"jn_6","cat":"gst","name":"GSTR-3B – Q3 (Oct–Dec) | QRMP Quarterly Filers","due":"22 Jan","freq":"Quarterly (Q3)","form":"GSTR-3B on GST Portal","who":"QRMP scheme taxpayers.","what":"File Q3 GSTR-3B and settle GST liability for October–December.","why":"Quarterly GST settlement for QRMP filers.","penalty":"Interest 18% p.a. + ₹50/day."},{"id":"jn_7","cat":"comp","name":"CMP-08 – Q3 Tax Payment (Oct–Dec) | Composition Dealers","due":"18 Jan","urgent":true,"freq":"Quarterly (Q3)","form":"CMP-08 on GST Portal","who":"GST Composition scheme taxpayers.","what":"Pay quarterly composition tax for October–December on the quarter's turnover. CMP-08 is a statement-cum-challan — file on portal and pay via GST Electronic Cash Ledger.","why":"Quarterly payment obligation for composition dealers. Ensure Q3 (Oct-Dec) turnover is correctly computed. Next due date: CMP-08 Q4 on 18 April.","penalty":"Interest 18% p.a. + ₹50/day late fee. Maximum late fee ₹10,000."},{"id":"jn_8","cat":"lab","name":"EPF Contribution – December Wages","due":"15 Jan","freq":"Monthly","form":"ECR via EPFO Portal","who":"EPFO-covered establishments.","what":"Deposit December PF contributions.","why":"Monthly statutory obligation.","penalty":"Damages 5–25% + interest 12% p.a."},{"id":"jn_9","cat":"lab","name":"ESIC Contribution – December Wages","due":"15 Jan","freq":"Monthly","form":"ESIC Portal","who":"ESIC-covered establishments.","what":"Deposit ESIC contributions for December.","why":"Monthly statutory obligation.","penalty":"Interest 12% p.a. + damages up to 25%."},{"id":"jn_10","cat":"lab","name":"Labour Welfare Fund – Jul–Dec Contribution","due":"15 Jan","freq":"Half-Yearly","form":"State LWF Authority / Online Portal","who":"All establishments in LWF-applicable states.","what":"Deposit LWF contributions for July–December period. Maharashtra rates: Employee ₹6/month + Employer ₹12/month per eligible employee.","why":"LWF contributes to worker welfare. Failure to deposit on time attracts penalties under the state LWF Act.","penalty":"State-specific interest and penalty. Maharashtra: interest 1%/month + fine up to ₹500."},{"id":"jn_11","cat":"lab","name":"Annual Returns – Factories Act / Shops & Establishments","due":"15 Jan","freq":"Annual","form":"Form 21 (Factories Act) / State Shops & Establishments Portal","who":"Factories registered under the Factories Act 1948. Shops and commercial establishments under the Shops & Establishments Act.","what":"File annual returns covering total workers employed, wages paid, leave records, overtime, accidents, and hazardous material usage (for factories).","why":"Annual returns provide the government with data on employment, wages, and working conditions. These feed into national labour statistics.","penalty":"Fine up to ₹2,000 for first offence and up to ₹5,000 for subsequent offences."},{"id":"jn_12","cat":"lab","name":"Professional Tax – December Deduction & Deposit","due":"Last day of Jan","freq":"Monthly","form":"State PT Portal","who":"PT-applicable employers.","what":"Deduct PT from December salaries and deposit.","why":"Monthly PT obligation.","penalty":"State-specific penalties."}]},"February":{"note":"<strong>Form 16A for Q3 due 15th February.</strong> In Maharashtra, February PT is ₹300 (higher than other months for salaries >₹10,000). Start collecting investment proofs for year-end salary TDS computation.","items":[{"id":"fb1","cat":"it","name":"TDS Deposit – January Deductions","due":"7 Feb","freq":"Monthly","form":"Challan 281","who":"All TDS deductors.","what":"Deposit TDS deducted from January payments.","why":"Monthly statutory obligation.","penalty":"Interest 1.5%/month on late deposit."},{"id":"fb2","cat":"it","name":"Form 16A – Non-Salary TDS Certificate (Q3: Oct–Dec)","due":"15 Feb","urgent":true,"freq":"Quarterly","form":"Form 16A from TRACES Portal","who":"All entities that deducted TDS on non-salary payments during October–December.","what":"Issue Form 16A for Q3 to all deductees. Download from TRACES after Q3 return (31 Jan) is processed. The Q3 Form 16A is particularly important for deductees who need to compute their advance tax.","why":"With only one month left in Q4, vendors and consultants need Q3 Form 16A urgently to finalize their own tax computations and advance tax.","penalty":"₹100/day u/s 272A for each delayed certificate."},{"id":"fb3","cat":"it","name":"Employee Investment Proofs Collection (for Salary TDS)","due":"By end of Feb","freq":"Annual","form":"Internal process – collect original/scanned investment proofs","who":"All employers who deduct salary TDS u/s 192.","what":"Collect actual investment proofs from employees for deductions claimed: Section 80C (PPF, LIC, ELSS, home loan principal), 80D (health insurance), 80G (donations), HRA (rent receipts), home loan interest certificate.","why":"TDS deducted through the year was based on estimated investments. February is the month to reconcile declarations with actual proofs. If investments are less than declared, additional TDS must be deducted in Feb–Mar.","penalty":"If TDS is short due to incorrect computation, employer is treated as defaulter under Section 201."},{"id":"fb4","cat":"gst","name":"GSTR-1 – January (Monthly Filers)","due":"11 Feb","freq":"Monthly","form":"GSTR-1 on GST Portal","who":"Monthly filers.","what":"Report all January sales invoices and outward supply details.","why":"Buyer ITC for January purchases.","penalty":"₹50/day max ₹10,000."},{"id":"fb5","cat":"gst","name":"GSTR-3B – January (Monthly Filers)","due":"20 Feb","freq":"Monthly","form":"GSTR-3B on GST Portal","who":"All regular GST taxpayers.","what":"File summary return and pay net GST for January.","why":"Primary GST payment return.","penalty":"Interest 18% p.a. + ₹50/day."},{"id":"fb6","cat":"lab","name":"EPF Contribution – January Wages","due":"15 Feb","freq":"Monthly","form":"ECR via EPFO Portal","who":"EPFO-covered establishments.","what":"Deposit January PF contributions.","why":"Monthly statutory obligation.","penalty":"Damages 5–25% + interest 12% p.a."},{"id":"fb7","cat":"lab","name":"ESIC Contribution – January Wages","due":"15 Feb","freq":"Monthly","form":"ESIC Portal","who":"ESIC-covered establishments.","what":"Deposit ESIC contributions for January.","why":"Monthly statutory obligation.","penalty":"Interest 12% p.a. + damages up to 25%."},{"id":"fb8","cat":"lab","name":"Professional Tax – January Deduction & Deposit","due":"Last day of Feb","freq":"Monthly","form":"State PT Portal","who":"PT-applicable employers.","what":"Deduct PT from January salaries and deposit. <strong>Note Maharashtra:</strong> February salaries attract ₹300 PT (instead of ₹200) for employees earning >₹10,000/month.","why":"Monthly PT obligation. February is special in Maharashtra with a higher PT rate.","penalty":"State-specific interest and penalty."},{"id":"fb9","cat":"lab","name":"Annual Return – Shops & Commercial Establishments","due":"1 Feb","freq":"Annual","form":"State Shops & Establishments Portal or Physical Submission","who":"All shops, commercial establishments, offices, and service businesses registered under the respective State Shops & Establishments Act.","what":"File annual return providing: number of employees (men/women/contract), total wages paid, leave granted and availed, working hours, holidays provided. Also renew establishment registration if annual renewal is due.","why":"The Shops & Establishments Act regulates working conditions in commercial establishments. Annual returns keep the labour department informed.","penalty":"Maharashtra: ₹2,000–₹10,000 for non-filing or false returns."}]},"March":{"note":"<strong>Final advance tax (15 Mar) and year-end compliance.</strong> Finalize salary TDS computation, ensure all year-end deductions are properly computed, and review P&L for any adjustments before 31st March.","items":[{"id":"mr1","cat":"it","name":"TDS Deposit – February Deductions","due":"7 Mar","freq":"Monthly","form":"Challan 281","who":"All TDS deductors.","what":"Deposit TDS deducted from February payments.","why":"Monthly statutory obligation.","penalty":"Interest 1.5%/month on late deposit."},{"id":"mr2","cat":"it","name":"Advance Tax – Final Installment (100% by 15 Mar)","due":"15 Mar","urgent":true,"freq":"Annual Final","form":"Challan 280 – Income Tax Portal","who":"All advance tax payers. Total advance tax must equal or exceed 90% of the total assessed tax for the year.","what":"Pay the final advance tax installment to cover 100% of the estimated annual tax liability. Review March income/expenses including: outstanding receivables, March salary cost, closing stock valuation, depreciation computation, and year-end provisions.","why":"If total advance tax < 90% of assessed tax by 15th March, interest u/s 234B @ 1% per month applies from April 1 until payment date.","penalty":"Interest u/s 234B: 1%/month if total advance tax < 90% of assessed tax. Interest u/s 234C on shortfall."},{"id":"mr3","cat":"it","name":"Finalize Salary TDS & Compute Form 16 Data","due":"31 Mar","freq":"Annual","form":"Internal calculation before Q4 TDS Return (due 31 May)","who":"All employers deducting salary TDS.","what":"Compute final TDS for each employee for the full year: (1) Finalize annual salary total, (2) Verify all investment proofs, (3) Compute taxable income net of exemptions and deductions, (4) Compute final tax, (5) Adjust for TDS already deducted Apr–Feb, (6) Deduct balance TDS in March salary.","why":"March is the final chance to rectify over/under TDS deduction on salary for the year.","penalty":"Employer treated as \"assessee in default\" u/s 201 if TDS is short. Interest 1.5%/month on shortfall."},{"id":"mr4","cat":"it","name":"Updated Income Tax Return (ITR-U) – 2 Years Prior","due":"31 Mar","freq":"Annual (if applicable)","form":"ITR-U on Income Tax Portal","who":"Taxpayers who need to correct errors or omissions in their ITR for AY 2022–23 (FY 2021–22).","what":"File an Updated Return (ITR-U) to declare any income that was omitted or incorrectly reported. Pay additional tax (25% of aggregate tax + interest if within 1 year; 50% if within 2 years).","why":"ITR-U provides a voluntary compliance window to correct past errors. Filing voluntarily is always better than being caught in scrutiny.","penalty":"If not filed voluntarily and discovered in scrutiny: penalty u/s 270A (50–200% of under-reported income tax) + possible prosecution."},{"id":"mr5","cat":"gst","name":"GSTR-1 – February (Monthly Filers)","due":"11 Mar","freq":"Monthly","form":"GSTR-1 on GST Portal","who":"Monthly filers.","what":"Report all February sales invoices. Start preparing for year-end GST reconciliation.","why":"Buyer ITC for February purchases.","penalty":"₹50/day max ₹10,000."},{"id":"mr6","cat":"gst","name":"GSTR-3B – February (Monthly Filers)","due":"20 Mar","freq":"Monthly","form":"GSTR-3B on GST Portal","who":"All regular GST taxpayers.","what":"File summary return and pay net GST for February.","why":"Primary GST payment return.","penalty":"Interest 18% p.a. + ₹50/day."},{"id":"mr7","cat":"gst","name":"Year-End GST Reconciliation (Books vs Returns)","due":"31 Mar","freq":"Annual","form":"Internal – GSTR-2B reconciliation in accounting software","who":"All GST-registered taxpayers.","what":"Reconcile GST ledgers in books against: (1) GSTR-3B data for the year, (2) GSTR-2B auto-populated ITC, (3) E-way bill data, (4) Outstanding receivables and payables. Identify any ITC not yet availed — it lapses after September return.","why":"March 31st is the last date for the GST year. After this, financial statements are finalized and annual returns (GSTR-9) are prepared.","penalty":"ITC not reconciled and later found ineligible: full reversal + 24% interest from date of availing."},{"id":"mr8","cat":"lab","name":"EPF Contribution – February Wages","due":"15 Mar","freq":"Monthly","form":"ECR via EPFO Portal","who":"EPFO-covered establishments.","what":"Deposit February PF contributions.","why":"Monthly statutory obligation.","penalty":"Damages 5–25% + interest 12% p.a."},{"id":"mr9","cat":"lab","name":"ESIC Contribution – February Wages","due":"15 Mar","freq":"Monthly","form":"ESIC Portal","who":"ESIC-covered establishments.","what":"Deposit ESIC contributions for February.","why":"Monthly statutory obligation.","penalty":"Interest 12% p.a. + damages up to 25%."},{"id":"mr10","cat":"lab","name":"Professional Tax – February Deduction & Deposit","due":"Last day of Mar","freq":"Monthly","form":"State PT Portal","who":"PT-applicable employers.","what":"Deduct PT from February salaries and deposit. In Maharashtra, February salary earners >₹10,000/month attract ₹300 PT. Plan March salary accordingly.","why":"Monthly PT obligation. Year-end: renew Enrollment Certificate if due for renewal.","penalty":"State-specific penalties."},{"id":"mr11","cat":"lab","name":"Annual PT Return & Employer Enrollment Renewal","due":"31 Mar","freq":"Annual","form":"State PT Authority / Online Portal","who":"All employers and self-employed professionals/proprietors in PT-applicable states.","what":"File annual Professional Tax return for the full year. Renew Employer's Enrollment Certificate if it is up for annual renewal. Pay any outstanding PT including the employer's own PT (₹2,500/year in Maharashtra).","why":"Year-end obligation to reconcile all PT deductions and deposits. Employer's own PT must be paid annually.","penalty":"Late renewal: penalty up to ₹5,000 in Maharashtra + interest."}]}};
